test('strips one pair of matching quotes', () => {
  const env = new EnvAccessor('A="one two"\nB=\'three\'\nC="mixed\'\n');
  assert.equal(env.get('A'), 'one two');
  assert.equal(env.get('B'), 'three');
  assert.equal(env.get('C'), '"mixed\'');
});

test('reads export KEY=value as KEY=value', () => {
  const env = new EnvAccessor('export HOST=localhost\n  export\tPORT="3000"\nexport   NAME = x y \nPLAIN=1\n');
  assert.deepEqual(env.all(), { HOST: 'localhost', PORT: '3000', NAME: 'x y', PLAIN: '1' });
  assert.equal(env.has('export HOST'), false);
});

test('treats an exported line as the line without the prefix', () => {
  const env = new EnvAccessor('export # not=a key\nexport =novalue\nexport\nexport \nexportKEY=kept\n# export COMMENTED=1\n');
  assert.deepEqual(env.all(), { exportKEY: 'kept' });
});

test('keeps a key that is named export', () => {
  const env = new EnvAccessor('export=1\nexport = 2\n');
  assert.equal(env.get('export'), '2');
  assert.deepEqual(env.all(), { export: '2' });
});

test('answers the fallback for a key that is not there', () => {
  const env = new EnvAccessor('KEY=value');
  assert.equal(env.get('MISSING', 'none'), 'none');
  assert.equal(env.has('KEY'), true);
  assert.equal(env.has('MISSING'), false);
});
